"""A tiny line-based state-machine DSL with validation and a runner.

Grammar (one definition per line):
    state NAME [initial]          -- declare a state; at most one may be initial
    on EVENT NAME -> NAME         -- transition: from-state, event, to-state
    # comments                    -- full-line or trailing comments are ignored
Blank lines are ignored.
"""

from __future__ import annotations

from dataclasses import dataclass, field


class MachineError(ValueError):
    """Base class for all DSL errors."""

    def __init__(self, message: str, line: int | None = None):
        self.line = line
        if line is not None:
            message = f"line {line}: {message}"
        super().__init__(message)


class TransitionError(MachineError):
    """Raised when an event has no transition from the current state."""


@dataclass(frozen=True)
class Transition:
    source: str
    event: str
    target: str


@dataclass
class Machine:
    states: set[str]
    initial: str
    transitions: dict[tuple[str, str], Transition]
    _state: str = field(init=False)
    history: list[str] = field(init=False)

    def __post_init__(self) -> None:
        self._state = self.initial
        self.history = [self.initial]

    @property
    def state(self) -> str:
        return self._state

    def send(self, event: str) -> str:
        key = (self._state, event)
        transition = self.transitions.get(key)
        if transition is None:
            raise TransitionError(
                f"no transition for event {event!r} in state {self._state!r}"
            )
        self._state = transition.target
        self.history.append(self._state)
        return self._state


def load(text: str) -> Machine:
    """Parse and validate DSL *text*; returns a ready-to-run Machine."""
    states: dict[str, int] = {}          # name -> declaring line
    initials: list[tuple[str, int]] = []  # (name, line)
    transitions: dict[tuple[str, str], Transition] = {}

    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        tokens = line.split()

        if tokens[0] == "state":
            if len(tokens) not in (2, 3) or (len(tokens) == 3 and tokens[2] != "initial"):
                raise MachineError(
                    f"malformed state declaration {raw.strip()!r}", lineno
                )
            name = tokens[1]
            if name in states:
                raise MachineError(f"duplicate state {name!r}", lineno)
            states[name] = lineno
            if len(tokens) == 3:
                initials.append((name, lineno))

        elif tokens[0] == "on":
            if (
                len(tokens) != 5
                or tokens[3] != "->"
            ):
                raise MachineError(
                    f"malformed transition {raw.strip()!r}, "
                    "expected 'on EVENT NAME -> NAME'",
                    lineno,
                )
            _, event, source, arrow, target = tokens
            key = (source, event)
            if key in transitions:
                raise MachineError(
                    f"duplicate transition for state {source!r} "
                    f"and event {event!r}",
                    lineno,
                )
            transitions[key] = Transition(source=source, event=event, target=target)

        else:
            raise MachineError(f"unknown directive {tokens[0]!r}", lineno)

    # Exactly one initial state.
    if not initials:
        raise MachineError("no initial state declared")
    if len(initials) > 1:
        details = ", ".join(f"{name!r} (line {ln})" for name, ln in initials)
        raise MachineError(
            f"multiple initial states declared: {details}",
            initials[1][1],
        )

    # Transitions must reference declared states.
    for (source, event), tr in transitions.items():
        decl_line = states.get(source)
        if decl_line is None:
            raise MachineError(
                f"transition references undeclared state {source!r} "
                f"(event {event!r})",
                decl_line if decl_line is not None else None,
            ) if False else MachineError(
                f"transition on event {event!r} references undeclared "
                f"source state {source!r}"
            )
        if tr.target not in states:
            raise MachineError(
                f"transition on event {event!r} from state {source!r} "
                f"references undeclared target state {tr.target!r}"
            )

    return Machine(states=set(states), initial=initials[0][0], transitions=transitions)

